import{_ as o,o as i,c as a,a as r}from"./app.Dzj71sBz.js";const g=JSON.parse('{"title":"Worktree, Commit, Version, and PR Governance Policy","description":"","frontmatter":{},"headers":[],"relativePath":"governance/WORKTREE_SCALE_COMMIT_VERSION_PR_POLICY.md","filePath":"governance/WORKTREE_SCALE_COMMIT_VERSION_PR_POLICY.md","lastUpdated":1771823011000}'),t={name:"governance/WORKTREE_SCALE_COMMIT_VERSION_PR_POLICY.md"};function l(c,e,n,d,s,m){return i(),a("div",null,[...e[0]||(e[0]=[r('<h1 id="worktree-commit-version-and-pr-governance-policy" tabindex="-1">Worktree, Commit, Version, and PR Governance Policy <a class="header-anchor" href="#worktree-commit-version-and-pr-governance-policy" aria-label="Permalink to &quot;Worktree, Commit, Version, and PR Governance Policy&quot;">​</a></h1><h2 id="purpose" tabindex="-1">Purpose <a class="header-anchor" href="#purpose" aria-label="Permalink to &quot;Purpose&quot;">​</a></h2><p>Define a single policy model for how work is placed, committed, versioned, and merged in multi-agent execution.</p><h2 id="core-rules" tabindex="-1">Core Rules <a class="header-anchor" href="#core-rules" aria-label="Permalink to &quot;Core Rules&quot;">​</a></h2><ol><li>Keep the primary checkout pinned to <code>main</code>.</li><li>Do not run feature branch development from the primary checkout.</li><li>Use policy-driven worktree placement, not <code>1 agent = 1 worktree</code>.</li><li>Use integration worktrees to merge/cherry-pick back to <code>main</code>.</li></ol><h2 id="task-scale-taxonomy" tabindex="-1">Task Scale Taxonomy <a class="header-anchor" href="#task-scale-taxonomy" aria-label="Permalink to &quot;Task Scale Taxonomy&quot;">​</a></h2><ol><li><code>XS</code>: single-file, low-risk, narrow change.</li><li><code>S</code>: small multi-file, bounded behavior change.</li><li><code>M</code>: cross-module feature/fix.</li><li><code>L</code>: cross-domain refactor or protocol/interface shift.</li><li><code>XL</code>: program-level change spanning lanes/phases.</li></ol><h2 id="worktree-allocation-matrix" tabindex="-1">Worktree Allocation Matrix <a class="header-anchor" href="#worktree-allocation-matrix" aria-label="Permalink to &quot;Worktree Allocation Matrix&quot;">​</a></h2><ol><li><code>XS</code>: shared lane worktree.</li><li><code>S</code>: shared lane worktree unless overlap-risk is high.</li><li><code>M</code>: lane-dedicated worktree, with burst worktree on contention.</li><li><code>L</code>: dedicated integration worktree plus optional burst worktrees.</li><li><code>XL</code>: program integration worktree plus multiple lane worktrees and merge train.</li></ol><h2 id="commit-strategy-matrix" tabindex="-1">Commit Strategy Matrix <a class="header-anchor" href="#commit-strategy-matrix" aria-label="Permalink to &quot;Commit Strategy Matrix&quot;">​</a></h2><ol><li><code>XS</code>: one commit (two maximum).</li><li><code>S</code>: micro-commits by concern (<code>logic</code>, <code>tests</code>, <code>docs</code>).</li><li><code>M</code>: micro-commit chain with topic boundaries.</li><li><code>L</code>: commit packages (<code>pkg</code>) per subsystem, then integration commit.</li><li><code>XL</code>: phased commit packages, stabilization commits, release tags.</li></ol><h2 id="micro-versioning-policy" tabindex="-1">Micro-Versioning Policy <a class="header-anchor" href="#micro-versioning-policy" aria-label="Permalink to &quot;Micro-Versioning Policy&quot;">​</a></h2><ol><li>Lane build marker: <code>lane.&lt;id&gt;.&lt;seq&gt;</code>.</li><li>Package marker: <code>pkg.&lt;domain&gt;.&lt;seq&gt;</code>.</li><li>Integration marker: <code>int.&lt;wave&gt;.&lt;seq&gt;</code>.</li><li>Promote to semver only at release boundary.</li></ol><h2 id="commit-package-contract" tabindex="-1">Commit Package Contract <a class="header-anchor" href="#commit-package-contract" aria-label="Permalink to &quot;Commit Package Contract&quot;">​</a></h2><ol><li><code>pkg</code> must be cohesive and cherry-pick safe.</li><li><code>pkg</code> must declare touched domain, risk class, and expected blast radius.</li><li><code>pkg</code> must include validation evidence and fix-forward guidance.</li><li><code>pkg</code> must avoid mixing unrelated domains.</li></ol><h2 id="pr-branch-topology" tabindex="-1">PR Branch Topology <a class="header-anchor" href="#pr-branch-topology" aria-label="Permalink to &quot;PR Branch Topology&quot;">​</a></h2><ol><li><code>lane/&lt;id&gt;-&lt;goal&gt;</code></li><li><code>pkg/&lt;domain&gt;-&lt;seq&gt;</code></li><li><code>int/&lt;wave&gt;-merge-train</code></li><li><code>hotfix/&lt;id&gt;</code></li></ol><h2 id="merge-policy" tabindex="-1">Merge Policy <a class="header-anchor" href="#merge-policy" aria-label="Permalink to &quot;Merge Policy&quot;">​</a></h2><ol><li><code>XS</code> and <code>S</code>: squash allowed if auditability is preserved.</li><li><code>M</code>: preserve bounded history until lane integration.</li><li><code>L</code> and <code>XL</code>: preserve package boundaries; no blind squash.</li><li>All final merges route through integration worktree controls.</li></ol><h2 id="conflict-policy" tabindex="-1">Conflict Policy <a class="header-anchor" href="#conflict-policy" aria-label="Permalink to &quot;Conflict Policy&quot;">​</a></h2><ol><li>Use file-claim/ownership checks before edits.</li><li>On conflict, fork/branch both outcomes and retain both artifacts.</li><li>Never destructively overwrite concurrent work.</li></ol>',21)])])}const p=o(t,[["render",l]]);export{g as __pageData,p as default};
